const modules = import.meta.glob('./*/index.js', { eager: true })

export const selectComponents = {}
export const previewComponents = {}
export const editComponents = {}
export const modulesList = []
export const modulesMap = {}

export const groupList = [
  {
    name: '图片',
    type: 'img'
  },
  {
    name: '辅助',
    type: 'assist'
  },
  {
    name: '业务',
    type: 'business'
  },
  {
    name: '功能',
    type: 'function'
  },
  {
    name: '画布',
    type: 'canvas'
  },
  {
    name: '预置画布',
    type: 'canvasTemplate'
  }
]

Object.keys(modules).forEach(modulePath => {
  const moduleName = modulePath.replace(/^\.\/(\w+)\/.*$/, '$1')
  const { Select, Preview, Edit, config } = modules[modulePath]

  if (!Select || !Preview || !Edit || !config) {
    console.warn(`模块${moduleName}缺少必要的配置`)
    return
  }

  selectComponents[`${moduleName}Select`] = Select
  previewComponents[`${moduleName}Preview`] = Preview
  editComponents[`${moduleName}Edit`] = Edit

  const { id, meta, data } = config

  modulesMap[id] = { name: moduleName, ...config }
  modulesList.push({
    name: moduleName,
    id,
    meta,
    data
  })
})

