<script setup>
import { ElMessage, ElMessageBox } from 'element-plus'
import { cloneDeep, isEmpty, isEqual } from 'lodash-es'
import VisualSelect from './VisualSelect.vue'
import VisualPreview from './VisualPreview.vue'
import VisualConfig from './VisualConfig.vue'
import VValidateConfig from './components/VValidateConfig/index.vue'
import { modulesMap } from './modules/index'

// import { A_getPresetCanvasList, A_getCustomCanvasList } from '@/api/siteConfig'

defineOptions({ name: 'VisualComponent' })

const props = defineProps({
  themeColor: {
    type: String,
    default: '#409EFF'
  },
  type: {
    type: String,
    required: true
  }
})

const model = defineModel({
  required: true
})

const visualConfig = reactive({
  openValidate: false,
  showOutline: false,
  activeModule: null,
  currentModule: null,
  currentModuleBackup: null,
  moduleList: [],
  validateStatus: 'pending',
  currentModuleValidate: () => Promise.resolve()
})
const pageConfig = reactive({
  backgroundColor: '#F7F8FA',
  space: 0,
  backgroundUrl: '',
  centerBackgroundUrl: '',
  bottomBackgroundUrl: ''
})
const validateConfigRef = ref(null)
const validateKey = ref(0)
const customCanvasList = ref([])
const presetCanvasList = ref([])
const visualKey = ref(0)
const pageType = toRef(props, 'type')

provide('visualConfig', visualConfig)
provide('pageConfig', pageConfig)
provide('unSaveModuleCheck', unSaveModuleCheck)
provide('scrollToCurrentModule', scrollToCurrentModule)
provide('pageType', pageType)
provide('updateCustomCanvasList', updateCustomCanvasList)
provide('getParentModule', getParentModule)

function init(val) {
  visualKey.value += 1
  const initData = val || model.value

  if (!initData) {
    resetData()
    return
  }
  try {
    const { pageConfig: actualPageConfig, moduleList } = JSON.parse(initData)
    const actualModuleList = moduleList.map(({ id, vid, visible, data }) => {
      if (id === '103' && data?.moduleList) {
        data.moduleList = data.moduleList.map(({ id, vid, visible, data: innerModuleData }) => ({
          ...cloneDeep(modulesMap[id]),
          vid,
          visible,
          data: innerModuleData
        }))
      }
      if (id === '104' && data?.list) {
        data.list = data.list.map(({ moduleList: innerModuleList, ...otherData }) => {
          return {
            ...otherData,
            moduleList: innerModuleList.map(({ id, vid, visible, data: innerModuleData }) => ({
              ...cloneDeep(modulesMap[id]),
              vid,
              visible,
              data: innerModuleData
            }))
          }
        })
      }
      return {
        ...cloneDeep(modulesMap[id]),
        vid,
        visible,
        data
      }
    })

    Object.assign(pageConfig, actualPageConfig)
    visualConfig.moduleList = [...actualModuleList]
  } catch (error) {
    // eslint-disable-next-line no-console
    console.log(error)
  }
}

function resetData() {
  visualConfig.moduleList = []
  Object.assign(pageConfig, {
    backgroundColor: '#F7F8FA',
    space: 0,
    backgroundUrl: '',
    centerBackgroundUrl: '',
    bottomBackgroundUrl: ''
  })
}

// async function updatePresetCanvasList() {
//   const { data: list } = await A_getPresetCanvasList({ page: 1, pageSize: 1000 })
//   presetCanvasList.value = list.map(item => {
//     const data = JSON.parse(item.json)
//     data.meta._cid = item.id
//     data.meta.type = 'canvasTemplate'
//     return data
//   })
// }

async function updateCustomCanvasList() {
  const res = await A_getCustomCanvasList()
  customCanvasList.value = res.map(item => {
    const data = JSON.parse(item.json)
    data.meta._cid = item.id
    data.meta.type = 'canvas'
    return data
  })
}

async function unSaveModuleCheck() {
  const { currentModule, currentModuleBackup } = visualConfig
  if (!currentModule) return Promise.resolve()

  if (visualConfig.openValidate) {
    await visualConfig.currentModuleValidate()
  }

  if (isEqual(currentModule.data, currentModuleBackup.data)) return Promise.resolve()
  return ElMessageBox.confirm('当前模块已修改，是否应用?', '提示', {
    confirmButtonText: '应用',
    cancelButtonText: '还原',
    type: 'warning'
  })
    .then(() => {
      currentModuleBackup.data = cloneDeep(currentModule.data)
      ElMessage({
        type: 'success',
        message: '模块应用成功'
      })
    })
    .catch(() => {
      currentModule.data = cloneDeep(currentModuleBackup.data)
      ElMessage({
        type: 'success',
        message: '模块配置已还原'
      })
    })
}

async function validate() {
  try {
    await validateConfigRef.value.validate()
  } catch (error) {
    nextTick(() => {
      visualConfig.currentModuleValidate()
    })
    throw error
  } finally {
    validateKey.value += 1
  }
}

async function save() {
  // 保存时必校验
  await validate()

  return unSaveModuleCheck().then(() => {
    const { moduleList } = visualConfig
    const data = {
      pageConfig,
      moduleList: moduleList.map(({ id, vid, visible, data }) => {
        const cloneData = cloneDeep(data)
        if (id === '103' && cloneData?.moduleList) {
          cloneData.moduleList = cloneData.moduleList.map(({ id, vid, visible, data }) => ({
            id,
            vid,
            visible,
            data
          }))
        }
        if (id === '104' && cloneData?.list) {
          cloneData.list = cloneData.list.map(({ moduleList: innerModuleList, ...otherData }) => {
            return {
              ...otherData,
              moduleList: innerModuleList.map(({ id, vid, visible, data: innerModuleData }) => ({
                id,
                vid,
                visible,
                data: innerModuleData
              }))
            }
          })
        }
        return { id, vid, visible, data: cloneData }
      })
    }
    model.value = JSON.stringify(data)
  })
}

function scrollToCurrentModule() {
  document.querySelector('.preview-item_current').scrollIntoView()
}

function toggleOutLine() {
  visualConfig.showOutline = !visualConfig.showOutline
}

function getParentModule (module) {
  if (isEmpty(module) || !model.value) return null

  let parentModule = null
  try {
    // const visualModuleData = typeof model.value === 'string' ? JSON.parse(model.value) : model.value
    const moduleList = visualConfig.moduleList || []
    parentModule = findParentComponentByVid(moduleList, module.vid)
  } catch (_err) {
    parentModule = null
  }

  return parentModule
}

/**
 * 在树形组件数据中，根据 module 的 vid 查找其直接父组件
 * @param {Array} components - 根组件数组（树的根节点列表）
 * @param {string} targetVId - 要查找的 module 的 vid
 * @returns {Object | null} - 返回父组件对象，若未找到则返回 null
 */
function findParentComponentByVid(components, targetVId) {
  for (const component of components) {
    if (Array.isArray(component.data?.moduleList)) {
      const found = component.data.moduleList.some(module => module.vid === targetVId)

      if (found) return component

      for (const module of component.data.moduleList) {
        const result = findParentComponentByVid([module], targetVId)
        if (result) return result
      }
    }
  }
  return null
}

// updateCustomCanvasList()
// updatePresetCanvasList()

defineExpose({
  init,
  save,
  validate,
  toggleOutLine,
  getParentModule
})
</script>

<template>
  <div :key="visualKey" class="visualize-container">
    <VisualSelect :custom-canvas-list="customCanvasList" :preset-canvas-list="presetCanvasList" />
    <VisualPreview />
    <VisualConfig>
      <template v-for="(_, name) in $slots" #[name]="slotProps">
        <slot :name="name" v-bind="slotProps" />
      </template>
    </VisualConfig>

    <VValidateConfig ref="validateConfigRef" :key="validateKey" />
