<script setup>
import { VueDraggable } from 'vue-draggable-plus'
import { nanoid } from 'nanoid'
import { cloneDeep } from 'lodash-es'
import { groupList, modulesList, selectComponents } from './modules/index'

defineOptions({
  name: 'VisualSelect',
  components: {
    ...selectComponents
  }
})

const props = defineProps({
  customCanvasList: {
    type: Array,
    default: () => []
  },
  presetCanvasList: {
    type: Array,
    default: () => []
  }
})

const activeNames = ref('img')
const visualConfig = inject('visualConfig')
const pageType = inject('pageType')
const modulesListGroup = ref({})

modulesList.sort((a, b) => a.meta.sort - b.meta.sort)

const showGroupList = computed(() => {
  return groupList.filter(group => {
    return modulesListGroup.value[group.type]?.length
  })
})

watch(
  [() => props.customCanvasList, () => props.presetCanvasList, pageType],
  () => {
    initModulesList()
  },
  { deep: true }
)

function initModulesList() {
  let acceptModuleList = []
  let showCanvasList = false
  modulesList
    .filter(item => item.meta.canUse === undefined || item.meta.canUse === true)
    .forEach(item => {
      const acceptType = item.meta.acceptType || ['home', 'micro']
      if (acceptType.includes(pageType.value)) {
        acceptModuleList.push(item)
        if (item.id === '201') {
          showCanvasList = true
        }
      }
    })
  if (showCanvasList) {
    acceptModuleList = [...acceptModuleList, ...props.customCanvasList]
  }

  if (showCanvasList) {
    acceptModuleList = [...acceptModuleList, ...props.presetCanvasList]
  }

  modulesListGroup.value = acceptModuleList.reduce((group, item) => {
    if (!group[item.meta.type]) {
      group[item.meta.type] = []
    }
    group[item.meta.type].push(item)
    return group
  }, {})
  if (import.meta.env.DEV) console.log('所有模块数据', modulesListGroup.value)
}

function handleClone(module) {
  const currentModule = {
    ...cloneDeep(module),
    vid: `vid-${nanoid(10)}`
  }

  return currentModule
}

function handleStart(e) {
  visualConfig.activeModule = JSON.parse(e.item.dataset.config)
}

function handleEnd() {
  visualConfig.activeModule = null
}

initModulesList()
</script>

