export function getVisibleConfig() {
  return {
    flag: true,
    dateVisible: false,
    dateVisibleType: 'weekly', // 'monthly' or 'weekly'
    dateVisibleRange: [], // number of days or weeks
    channelVisible: false,
    channelVisibleList: []
  }
}

import ExcelJS from 'exceljs'

export * from './config'

export function readAsArrayBufferAsync(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(reader.result)
    reader.onerror = reject
    reader.readAsArrayBuffer(file)
  })
}

export async function readExcelArrayBufferAsync(arrayBuffer) {
  const data = []
  const workbook = new ExcelJS.Workbook()
  await workbook.xlsx.load(arrayBuffer)
  const worksheet = workbook.getWorksheet(1)

  const rows = worksheet.getRows(1, worksheet.rowCount)
  for (let i = 0; i < rows.length; i++) {
    const row = rows[i]
    const rowData = []
    for (let j = 1; j < row.values.length; j++) {
      rowData.push(row.values[j])
    }
    data.push(rowData)
  }

  return {
    rowCount: worksheet.rowCount,
    columnCount: worksheet.columnCount,
    data
  }
}

