<script setup>
import { useClipboard } from '@vueuse/core'
import { nanoid } from 'nanoid'
import { modulesMap } from '../../modules/index'
import IconCheck from '@/VisualComponent/icons/IconCheck.vue'
import IconCopy from '@/VisualComponent/icons/IconCopy.vue'
import IconPaste from '@/VisualComponent/icons/IconPaste.vue'

defineOptions({
  name: 'VControlBar'
})

const visualConfig = inject('visualConfig')
const pageConfig = inject('pageConfig')

const { openValidate } = toRefs(visualConfig)

const { copy } = useClipboard({
  legacy: true
})

const pasteDialogVisible = ref(false)
const keepBusinessData = ref(true)
const pasteType = ref('')
const pasteData = ref(null)

function copyPage() {
  copy(
    JSON.stringify({
      pageConfig,
      moduleList: visualConfig.moduleList.map(({ id, vid, visible, data }) => ({
        id,
        vid,
        visible,
        data
      }))
    })
  )
  ElMessage.success('复制成功')
}

function copyComponent() {
  if (!visualConfig.currentModule) {
    ElMessage.warning('请先选择要复制的模块')
    return
  }
  copy(JSON.stringify(visualConfig.currentModule))
  ElMessage.success('复制成功')
}

async function getCopyData() {
  const text = await navigator.clipboard.readText()
  let copyData = null
  if (!text || text === 'null') {
    ElMessage.error('复制内容为空')
    return null
  }
  try {
    copyData = JSON.parse(text)
  } catch (error) {
    ElMessage.error('复制内容格式错误')
    return null
  }

  const { pageConfig, moduleList, id, meta, vid, data } = copyData
  let type = ''

  if (pageConfig && moduleList) {
    type = 'page'
  } else if (id && meta && vid && data) {
    type = 'component'
  } else {
    ElMessage.error('复制内容格式错误')
    return null
  }

  return { type, copyData }
}

async function handlePaste() {
  const data = await getCopyData()
  if (!data) return
  const { type, copyData } = data

  pasteType.value = type
  pasteData.value = copyData
  pasteDialogVisible.value = true
}

function handlePasteConfirm() {
  if (!keepBusinessData.value) {
    resetEvents(pasteData.value)
  }

  if (pasteType.value === 'page') {
    const { pageConfig: actualPageConfig, moduleList } = pasteData.value
    const actualModuleList = moduleList.map(({ id, vid, visible, data }) => {
      return {
        ...modulesMap[id],
        vid,
        visible,
        data
      }
    })

    Object.assign(pageConfig, actualPageConfig)
    visualConfig.moduleList = [...actualModuleList]
    ElNotification({
      title: '成功',
      message: '粘贴页面数据成功',
      type: 'success'
    })
  } else {
    pasteData.value.vid = `vid-${nanoid(10)}`
    const currentIndex = visualConfig.moduleList.findIndex(item => item.id === visualConfig.currentModule?.id)
    if (currentIndex !== -1) {
      visualConfig.moduleList.splice(currentIndex + 1, 0, pasteData.value)
    } else {
      visualConfig.moduleList.push(pasteData.value)
    }
    ElNotification({
      title: '成功',
      message: '粘贴模块数据成功',
      type: 'success'
    })
  }
  closeDialog()
}

function resetEvents(obj) {
  const newValue = { type: 'NO', data: {} }
  // 检查对象是否为数组或普通对象
  if (Array.isArray(obj)) {
    obj.forEach(item => resetEvents(item))
  } else if (typeof obj === 'object' && obj !== null) {
    // 遍历对象的每个键
    for (const key in obj) {
      if (key === 'event') {
        // 如果是 event 键，重置其值
        obj[key] = { ...newValue }
      } else {
        // 递归处理嵌套对象
        resetEvents(obj[key])
      }
    }
  }
}

function closeDialog() {
  pasteDialogVisible.value = false
  keepBusinessData.value = true // 重置为默认值
}
</script>

