        const exists = currentModuleData.value.servicesList.some(item => item.serveId === serviceDetail.serveId)
        if (!exists) {
          currentModuleData.value.servicesList.push({ ...serviceDetail })
        }
        delete data.serviceDetail
      }
    }
  })
}

// 清空动作
function handleChangeVGoodsList(goodsList) {
  console.log('goodsList', goodsList)
  // currentModuleData.value.goodsList = goodsList
  dialogSelection.value = normalizeDialogSelectionList(goodsList)
  if (!currentModuleData.value.goodsList.length) {
    initData()
  }
}

function handleChange(selection) {
  currentModuleData.value.goodsList = selection
  if (!currentModuleData.value.goodsList.length) {
    currentModuleData.value.goodsList = []
    initData()
  }
}

onMounted(async () => {
  initData()
  if (showCanvasGoods.value && currentModuleData.value.goodsList?.length) {
    await fetchGoodsListInfo(getGoodsSpuCodeList(currentModuleData.value.goodsList))
  }
  emit('mounted')
})

function getValidGoodsList(list) {
  return Array.isArray(list) ? list.filter(Boolean) : []
}

function normalizeDialogSelectionList(list) {
  return getValidGoodsList(list)
    .map(item => formatDialogSelection(item))
    .filter(item => item?.spuCode)
}

function getSkuKey(item) {
  return item?.equityCode || item?.skuCode || item?.skuId || item?.eShopSkuId || item?.id || ''
}

function getGoodsSpuCode(item) {
  return item?.spuCode || item?.equityCode || item?.skuCode || item?.skuId || item?.eShopSkuId || item?.id || ''
}

function getGoodsSpuCodeList(list) {
  return [...new Set(getValidGoodsList(list).map(getGoodsSpuCode).filter(Boolean))]
}

function hasSortType(val) {
  return val !== '' && val !== undefined && val !== null
}

async function fetchGoodsListInfo(spuCodeList) {
  if (!spuCodeList.length) {
    currentModuleData.value.goodsList = []
    return
  }

  const sortType = currentModuleData.value.goodsSortType
  const sortTypeMap = { 0: null, 1: false, 2: true }
  const priceOrderBy = sortTypeMap[sortType] ?? null
  const API = hasSortType(sortType) ? A_getAdvertSkuSortBySortType : A_getAdvertSkuInfoBySkus
  const res = await API({ spuCodeList, priceOrderBy, current: 1, size: 100 })

  currentModuleData.value.goodsList = (res?.records ?? []).map(item => goodsMultipleFormat(item))
}

// PickGoods 按 group 勾选，编辑区列表需要展示 group 下的全部子商品。
function expandGroupsToGoodsList(list) {
  return getValidGoodsList(list).flatMap(group => {
    const skuDetails = getValidGoodsList(group?.skuDetails)
    if (!skuDetails.length) {
      return group?.spuCode ? [{ ...group, spuCode: group.spuCode }] : []
    }
    return skuDetails.map(item => ({
      ...item,
      spuCode: item?.spuCode || group?.spuCode || ''
    }))
  })
}

function syncDialogSelectionFromGoodsList() {
  const goodsList = getValidGoodsList(currentModuleData.value.goodsList)
  const currentGroupList = getValidGoodsList(dialogSelection.value)

  if (!currentGroupList.length) {
    dialogSelection.value = normalizeDialogSelectionList(goodsList).filter(
      (item, index, array) => array.findIndex(current => current?.spuCode === item?.spuCode) === index
    )
    return
  }

  const currentGoodsKeySet = new Set(goodsList.map(item => getSkuKey(item)).filter(Boolean))
  dialogSelection.value = currentGroupList.filter(group => {
    const skuDetails = getValidGoodsList(group?.skuDetails)
    if (!skuDetails.length) {
      return goodsList.some(item => item?.spuCode === group?.spuCode)
    }
    return skuDetails.every(item => currentGoodsKeySet.has(getSkuKey(item)))
  })
}

async function syncListFromDialogSelection() {
  const goodsList = expandGroupsToGoodsList(dialogSelection.value)
  await fetchGoodsListInfo(getGoodsSpuCodeList(goodsList))
}

function sortDialogSelectionByPreviousOrder(list) {
  const nextSelection = normalizeDialogSelectionList(list)
  const previousSpuCodeList = getGoodsSpuCodeList(currentModuleData.value.goodsList)
  const nextSelectionMap = new Map(nextSelection.map(item => [item?.spuCode, item]))
  const orderedSelection = previousSpuCodeList.map(spuCode => nextSelectionMap.get(spuCode)).filter(Boolean)
  const orderedSelectionCodeSet = new Set(orderedSelection.map(item => item?.spuCode).filter(Boolean))
  const appendedSelection = nextSelection.filter(item => !orderedSelectionCodeSet.has(item?.spuCode))
  return [...orderedSelection, ...appendedSelection]
}

async function handleConfirmPickGoods(selected) {
  dialogSelection.value = sortDialogSelectionByPreviousOrder(selected)
  await syncListFromDialogSelection()
  if (!currentModuleData.value.goodsList.length) {
    currentModuleData.value.goodsList = []
    initData()
  }
}

function formatDialogSelection(item) {
  if (!item || typeof item !== 'object') return item
  return {
    ...item,
    spuCode: item.spuCode || item.eShopSkuId || item.equityCode || item.skuCode || '',
    classify: item.classify ?? item.equityType ?? item.equityTypeId ?? 1
  }
}

defineExpose({
  validate
})
</script>

