<script setup>
import { VueDraggable } from 'vue-draggable-plus'
import Moveable from 'vue3-moveable'
import WidgetPreviewItem from '../WidgetPreviewItem/index.vue'
import { previewComponents } from '../../widgets/index.js'
import { Delete, Top, Bottom, CopyDocument } from '@element-plus/icons-vue'
import ClickInput from '../ClickInput/index.vue'
import { nanoid } from 'nanoid'
import { cloneDeep } from 'lodash-es'

defineOptions({
  name: 'CanvasMain',
  components: {
    ...previewComponents
  }
})

const customCanvasConfig = inject('customCanvasConfig')

const canvasRef = ref(null)
const moveableRef = ref(null)
const widgetRefs = reactive({})

let goodsIndex = 0
let serviceIndex = 0

const { currentWidget, moduleConfig, servicesList, goodsList } = toRefs(customCanvasConfig)
const canvasWidth = computed(() => {
  return moduleConfig.value.hasMargin ? 702 : 750
})

function handleResize(e) {
  e.target.style.height = `${e.height}px`
  moduleConfig.value.height = e.height
}

function handleClick(widget) {
  if (currentWidget.value && currentWidget.value.wid === widget.wid) return
  customCanvasConfig.currentWidget = widget
}

function handleDeleteClick() {
  if (currentWidget.value) {
    const index = customCanvasConfig.widgetList.findIndex(item => item.wid === currentWidget.value.wid)
    customCanvasConfig.widgetList.splice(index, 1)
    customCanvasConfig.currentWidget = null
  }
}

function handleTopClick() {
  if (currentWidget.value.data.zIndex === undefined) {
    currentWidget.value.data.zIndex = 100
  }
  currentWidget.value.data.zIndex++
}

function handleBottomClick() {
  if (currentWidget.value.data.zIndex === undefined) {
    currentWidget.value.data.zIndex = 100
  }
  if (currentWidget.value.data.zIndex === 0) {
    ElMessage.warning('已经是最低层级，请升高其他组件层级！')
    return
  }
  currentWidget.value.data.zIndex--
}

function changeStyle(key, value) {
  widgetRefs[currentWidget.value.wid].setStyle(key, value)
}

function handleCopyClick() {
  const copyData = {
    ...cloneDeep(currentWidget.value),
    wid: `wid-${nanoid(10)}`
  }
  copyData.data.top = currentWidget.value.data.top + 20
  copyData.data.left = currentWidget.value.data.left + 20

  customCanvasConfig.widgetList.push(copyData)
}

// 添加键盘控制功能
function handleKeyDown(e) {
  if (!currentWidget.value) return

  // 默认移动步长
  const step = e.shiftKey ? 10 : 1
  let key = null
  let value = null

  switch (e.key) {
    case 'ArrowUp':
      key = 'top'
      value = currentWidget.value.data.top - step
      break
    case 'ArrowDown':
      key = 'top'
      value = currentWidget.value.data.top + step
      break
    case 'ArrowLeft':
      key = 'left'
      value = currentWidget.value.data.left - step
      break
    case 'ArrowRight':
      key = 'left'
      value = currentWidget.value.data.left + step
      break
    default:
      return
  }

  // 防止组件移出画布
  if (key === 'top') {
    value = Math.max(0, Math.min(value, moduleConfig.value.height - currentWidget.value.data.height))
  } else if (key === 'left') {
    value = Math.max(0, Math.min(value, canvasWidth.value - currentWidget.value.data.width))
  }

  changeStyle(key, value)
  e.preventDefault() // 阻止默认行为，防止页面滚动
}

function getDetailsData(id, index) {
  if (index === 0) {
    goodsIndex = 0
    serviceIndex = 0
  }
  if (id === 'W006' && goodsList.value?.length) {
    return goodsList.value[goodsIndex++]
  }
  if (id === 'W007' && servicesList.value?.length) {
    return servicesList.value[serviceIndex++]
  }
}

onMounted(() => {
  nextTick(() => {
    moveableRef.value.updateRect()
    window.addEventListener('keydown', handleKeyDown)
  })
})

// 组件卸载时移除事件监听
onUnmounted(() => {
  window.removeEventListener('keydown', handleKeyDown)
})

function formatNumber(num) {
  return num?.toFixed(3) ?? num
}
</script>

